    #[cfg(coverage)]
    #[test]
    fn free_variable_scan_optional_branches_are_exercised_for_coverage() {
        let context = Context::create();
        let codegen = CodeGen::new(&context, "coverage_free_variable_scan_optional_branches");

        let span = Span::new(1, 1);

        {
            let mut bound: HashSet<String> = HashSet::new();
            let mut free: HashSet<String> = HashSet::new();
            codegen.collect_free_vars_stmt(
                &Stmt::VarDecl {
                    name: "x".to_string(),
                    initializer: None,
                    span,
                },
                &mut bound,
                &mut free,
            );
            codegen.collect_free_vars_stmt(
                &Stmt::VarDecl {
                    name: "y".to_string(),
                    initializer: Some(Expr::Variable {
                        name: "z".to_string(),
                        span,
                    }),
                    span,
                },
                &mut bound,
                &mut free,
            );
        }

        {
            let mut bound: HashSet<String> = HashSet::new();
            let mut free: HashSet<String> = HashSet::new();
            codegen.collect_free_vars_stmt(
                &Stmt::Return { value: None, span },
                &mut bound,
                &mut free,
            );
            codegen.collect_free_vars_stmt(
                &Stmt::Return {
                    value: Some(Expr::Variable {
                        name: "r".to_string(),
                        span,
                    }),
                    span,
                },
                &mut bound,
                &mut free,
            );
        }

        {
            let mut bound: HashSet<String> = HashSet::new();
            let mut free: HashSet<String> = HashSet::new();
            codegen.collect_free_vars_stmt(
                &Stmt::Assert {
                    condition: Expr::Variable {
                        name: "cond".to_string(),
                        span,
                    },
                    message: None,
                    span,
                },
                &mut bound,
                &mut free,
            );
            codegen.collect_free_vars_stmt(
                &Stmt::Assert {
                    condition: Expr::Variable {
                        name: "cond2".to_string(),
                        span,
                    },
                    message: Some(Expr::Variable {
                        name: "msg".to_string(),
                        span,
                    }),
                    span,
                },
                &mut bound,
                &mut free,
            );
        }

        {
            let body = Box::new(Stmt::Block {
                statements: Vec::new(),
                span,
            });
            let iterable = Expr::List {
                elements: Vec::new(),
                span,
            };

            let mut bound: HashSet<String> = HashSet::new();
            let mut free: HashSet<String> = HashSet::new();
            codegen.collect_free_vars_stmt(
                &Stmt::For {
                    variable: "i".to_string(),
                    iterable: iterable.clone(),
                    body: body.clone(),
                    span,
                },
                &mut bound,
                &mut free,
            );

            bound.insert("j".to_string());
            codegen.collect_free_vars_stmt(
                &Stmt::For {
                    variable: "j".to_string(),
                    iterable,
                    body,
                    span,
                },
                &mut bound,
                &mut free,
            );
        }

        {
            let try_block = Box::new(Stmt::Block {
                statements: Vec::new(),
                span,
            });
            let catch_block = Box::new(Stmt::Block {
                statements: Vec::new(),
                span,
            });

            let mut bound: HashSet<String> = HashSet::new();
            let mut free: HashSet<String> = HashSet::new();
            codegen.collect_free_vars_stmt(
                &Stmt::TryCatch {
                    try_block: try_block.clone(),
                    error_name: "e".to_string(),
                    catch_block: catch_block.clone(),
                    span,
                },
                &mut bound,
                &mut free,
            );

            bound.insert("f".to_string());
            codegen.collect_free_vars_stmt(
                &Stmt::TryCatch {
                    try_block,
                    error_name: "f".to_string(),
                    catch_block,
                    span,
                },
                &mut bound,
                &mut free,
            );
        }
    }

